export const STYLE = ":root {\n  color-scheme: light dark;\n  --fg: #1f2328;\n  --muted: #656d76;\n  --line: #d0d7de;\n  --bg: #fff;\n  --soft: #f6f8fa;\n  --soft-fg: var(--fg);\n  --accent: #0969da;\n  --link: var(--accent);\n  --bad: #cf222e;\n  --good: #1a7f37;\n  --warn: #9a6700;\n  --primary: var(--good);\n  --primary-fg: #fff;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    --fg: #e6edf3;\n    --muted: #8d96a0;\n    --line: #30363d;\n    --bg: #0d1117;\n    --soft: #161b22;\n    --accent: #4493f8;\n    --bad: #f85149;\n    --good: #3fb950;\n    --warn: #d29922;\n  }\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  font:\n    14px/1.45 system-ui,\n    -apple-system,\n    'Segoe UI',\n    sans-serif;\n  color: var(--fg);\n  background: var(--bg);\n}\n\nheader {\n  position: sticky;\n  top: 0;\n  z-index: 1;\n  background: var(--bg);\n  border-bottom: 1px solid var(--line);\n  padding: 12px 20px;\n}\n\nh1 {\n  font-size: 16px;\n  margin: 0 0 4px;\n}\n\n.meta,\n.note {\n  color: var(--muted);\n  font-size: 12px;\n}\n\n.meta code {\n  font-size: 12px;\n}\n\n.note {\n  margin-top: 6px;\n}\n\n.bar {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n  flex-wrap: wrap;\n  margin-top: 10px;\n}\n\n.bar .spacer {\n  flex: 1;\n}\n\n.counts span {\n  margin-right: 10px;\n}\n\nbutton,\n.bar select {\n  font: inherit;\n  border: 1px solid var(--line);\n  background: var(--soft);\n  color: var(--soft-fg);\n  border-radius: 6px;\n  padding: 4px 10px;\n  cursor: pointer;\n}\n\nbutton:hover:not(:disabled) {\n  border-color: var(--muted);\n}\n\nbutton:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\nbutton.primary {\n  background: var(--primary);\n  border-color: var(--primary);\n  color: var(--primary-fg);\n}\n\nmain {\n  padding: 0 20px 40px;\n}\n\ntable {\n  width: 100%;\n  border-collapse: collapse;\n  margin-top: 8px;\n}\n\nth,\ntd {\n  text-align: left;\n  vertical-align: top;\n  padding: 8px;\n  border-bottom: 1px solid var(--line);\n}\n\nth {\n  font-size: 12px;\n  color: var(--muted);\n  font-weight: 600;\n}\n\ntd.num {\n  width: 36px;\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n}\n\n.text {\n  font-weight: 500;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.where,\n.preview {\n  font-size: 12px;\n  margin-top: 2px;\n}\n\n.where a,\n.preview a {\n  color: var(--link);\n  text-decoration: none;\n}\n\n.snippet {\n  display: block;\n  margin-top: 4px;\n  font:\n    12px ui-monospace,\n    monospace;\n  color: var(--muted);\n  white-space: pre-wrap;\n  word-break: break-all;\n}\n\n.seg {\n  display: inline-flex;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  overflow: hidden;\n}\n\n/* Comment markers between lit children break `button + button`. */\n.seg button {\n  border: 0;\n  border-left: 1px solid var(--line);\n  border-radius: 0;\n  background: transparent;\n  color: var(--fg);\n  padding: 3px 10px;\n}\n\n.seg button:first-of-type {\n  border-left: 0;\n}\n\n.seg button[aria-pressed='true'] {\n  background: var(--accent);\n  color: #fff;\n}\n\ninput[type='text'],\nselect {\n  font:\n    13px ui-monospace,\n    monospace;\n  width: 100%;\n  min-width: 220px;\n  padding: 4px 6px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  background: var(--bg);\n  color: var(--fg);\n}\n\n.bar select {\n  font: inherit;\n  width: auto;\n  min-width: 0;\n}\n\ninput.bad,\nselect.bad {\n  border-color: var(--bad);\n}\n\ninput.warn,\nselect.warn {\n  border-color: var(--warn);\n}\n\n.status {\n  font-size: 12px;\n  margin-top: 4px;\n  min-height: 16px;\n}\n\n.status.bad {\n  color: var(--bad);\n}\n\n.status.ok {\n  color: var(--good);\n}\n\n.status.warn {\n  color: var(--warn);\n}\n\n.hint {\n  font-size: 12px;\n  color: var(--muted);\n}\n\ntr.skip .text,\ntr.skip .where,\ntr.skip .preview {\n  opacity: 0.5;\n}\n\n.badge {\n  font-size: 11px;\n  padding: 0 5px;\n  border-radius: 8px;\n  border: 1px solid var(--line);\n  color: var(--muted);\n  margin-right: 4px;\n}\n\n.badges {\n  margin-top: 4px;\n}\n\n.done {\n  padding: 60px 20px;\n  text-align: center;\n}\n\n.done h2 {\n  font-size: 18px;\n}\n\nlabel.filter {\n  font-size: 12px;\n  color: var(--muted);\n  display: inline-flex;\n  gap: 4px;\n  align-items: center;\n}\n\n.bad-text {\n  color: var(--bad);\n}\n\n.warn-text {\n  color: var(--warn);\n}\n\n.pair {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px;\n  margin-top: 6px;\n}\n\n.box {\n  background: var(--soft);\n  border-radius: 6px;\n  padding: 6px 8px;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.box .label {\n  display: block;\n  font-size: 11px;\n  color: var(--muted);\n  margin-bottom: 2px;\n}\n\n.locale {\n  margin-top: 10px;\n  padding-top: 8px;\n  border-top: 1px dashed var(--line);\n}\n\n.locale:first-of-type {\n  margin-top: 0;\n  border-top: 0;\n  padding-top: 0;\n}\n\ntd.detail {\n  background: var(--soft);\n}\n\n:root:has(body[data-host='webview']) {\n  color-scheme: normal;\n  --fg: var(--vscode-foreground);\n  --muted: var(--vscode-descriptionForeground);\n  --line: var(--vscode-widget-border, var(--vscode-panel-border));\n  --bg: var(--vscode-editor-background);\n  --soft: var(--vscode-button-secondaryBackground);\n  --soft-fg: var(--vscode-button-secondaryForeground);\n  --accent: var(--vscode-focusBorder);\n  --link: var(--vscode-textLink-foreground);\n  --bad: var(--vscode-errorForeground);\n  --good: var(--vscode-testing-iconPassed);\n  --warn: var(--vscode-editorWarning-foreground);\n  --primary: var(--vscode-button-background);\n  --primary-fg: var(--vscode-button-foreground);\n}\n\nbody[data-host='webview'] {\n  font-family: var(--vscode-font-family);\n}\n\nbody[data-host='webview'] input[type='text'],\nbody[data-host='webview'] select {\n  background: var(--vscode-input-background);\n  color: var(--vscode-input-foreground);\n}\n"
